def make_palindrome(s: str) -> str:
    """Return the shortest palindrome that starts with the given string."""
    if s == s[::-1]:
        return s

    # Find the longest suffix of s that is a palindrome
    for i in range(len(s)):
        if s[i:] == s[i:][::-1]:
            # Append the reverse of the prefix to make a palindrome
            return s + s[:i][::-1]

    # In the worst case, the entire string is reversed
    return s + s[::-1]
