    def maxSlidingWindow(self, nums, k):
        max_arr = []
        max_index = 0
        if k == 1:
            return nums

        def update(i):
            nonlocal max_index, max_arr
            if i > max_index and nums[i] >= nums[max_index]:
                max_index = i
            if i >= k and nums[i - k] == nums[max_index]:
                max_index = i - k + max_index
            max_arr.append(nums[max_index])

        for i in range(0, len(nums)):
            if i >= k:
                update(i)
            else:
                max_index = i
                max_arr.append(nums[max_index])
        return max_arr


