    if len(lst) < 2:
        return True

    # Count occurrences of each number
    count = {}
    for num in lst:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    # Check if the list is sorted and has more than one duplicate
    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            return False
        if count[lst[i]] > 1:
