def even_odd_count(num):
    even_count = 0
    odd_count = 0

    # Loop through each digit in the number
    while num != 0:
        digit = num % 10  # Get the last digit
        if digit % 2 == 0:
            even_count += 1  # Increment even count if the digit is even
        else:
            odd_count += 1  # Increment odd count if the digit is odd
